using System.Net;
using System.Net.Http.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class MobileFinanceTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>{
 private sealed record Fixture(string User,Guid Property,Guid Unit,Guid Other,Guid Membership,Guid OwnerLink,Guid UnitCharge,Guid OwnerCharge,Guid TenantCharge,Guid HiddenCharge);
 private static DateOnly Today=>DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Europe/Istanbul")).DateTime);
 private async Task<Fixture> Setup(){
  var user=Guid.NewGuid().ToString();var p=new Property("Finance fixture","City","District","Address");var b=p.AddBuilding("A");var unit=b.AddUnit("1",1,90m);var other=b.AddUnit("2",2,90m);var member=new PropertyMembership(p.Id,user);
  Person Person(string name,string linked){var person=new Person(p.Id,name,"Private","5550000000","private@example.test");person.SetProfile("NATURAL","FOREIGN","US","HIDDEN123",null,null,null,linked);return person;}
  var owner=Person("Owner",user);var tenant=Person("Tenant",user);var hidden=Person("Hidden",Guid.NewGuid().ToString());
  var o=new UnitOccupancy(p.Id,unit.Id,owner.Id,OccupancyType.OWNER,Today.AddYears(-2));var t=new UnitOccupancy(p.Id,unit.Id,tenant.Id,OccupancyType.TENANT,Today.AddYears(-2));var h=new UnitOccupancy(p.Id,unit.Id,hidden.Id,OccupancyType.TENANT,Today.AddYears(-2));
  DuesAssessment Assessment(int month,decimal amount,string role){return new DuesAssessment(p.Id,Guid.NewGuid(),new string('a',64),new DateOnly(Today.Year,Today.Month,1).AddMonths(month),amount,"TRY",Today.AddDays(-1),"Fixture",role);}
  var a=Assessment(0,100.10m,"UNIT");var c=a.AddCharge(unit.Id);a.AddCharge(other.Id);
  var oa=Assessment(-1,300.30m,"OWNER");var oc=oa.AddCharge(unit.Id);oc.RecordParties([new DuesChargeParty(oc,o,owner,true)]);
  var ta=Assessment(-2,80.20m,"TENANT");var tc=ta.AddCharge(unit.Id);tc.RecordParties([new DuesChargeParty(tc,t,tenant,true)]);
  var ha=Assessment(-3,400.40m,"TENANT");var hc=ha.AddCharge(unit.Id);hc.RecordParties([new DuesChargeParty(hc,h,hidden,true)]);
  Payment Pay(DuesCharge charge,decimal amount){var pay=new Payment(p.Id,unit.Id,Guid.NewGuid(),new string('b',64),amount,"TRY",Today,PaymentMethod.BANK_TRANSFER,"private-"+Guid.NewGuid(),"Private bank description");pay.Allocate(charge,amount);pay.ValidateComplete();return pay;}
  var cp=Pay(c,30.05m);var op=Pay(oc,40.20m);var tp=Pay(tc,20.10m);var hp=Pay(hc,10.01m);var reversed=Pay(c,10.01m);reversed.Cancel("Fixture reversal",DateTimeOffset.UtcNow);c.ReversePayment(10.01m);
  await factory.WithDb(async db=>{db.AddRange(p,member,owner,tenant,hidden,o,t,h,a,oa,ta,ha,cp,op,tp,hp,reversed);await db.SaveChangesAsync();});return new(user,p.Id,unit.Id,other.Id,member.Id,o.Id,c.Id,oc.Id,tc.Id,hc.Id);
 }
 private static string Path(Fixture f,string role="OWNER",string view="charges",int page=1,Guid? charge=null,Guid? unit=null)=>$"/api/v1/mobile/finance?propertyId={f.Property}&role={role}&view={view}&page={page}"+(role is "OWNER" or "TENANT"?$"&unitId={unit??f.Unit}":unit!=null?$"&unitId={unit}":"")+(charge!=null?$"&chargeId={charge}":"");
 [PostgresFact]public async Task OwnerAndTenantSeeOnlyAuthorizedChargesAndMinimalAllocationHistory(){var f=await Setup();using var c=TestToken.Client(factory,f.User,"RESIDENT");var owner=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f)))!;Assert.Equal("400.40",owner.Summary.Amount);Assert.Equal("70.25",owner.Summary.Paid);Assert.Equal("330.15",owner.Summary.Balance);Assert.Equal(2,owner.Charges.Length);Assert.DoesNotContain(owner.Charges,x=>x.Charge.Id==f.TenantCharge||x.Charge.Id==f.HiddenCharge);var tenant=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f,"TENANT")))!;Assert.Equal("130.15",tenant.Summary.Balance);Assert.DoesNotContain(tenant.Charges,x=>x.Charge.Id==f.OwnerCharge||x.Charge.Id==f.HiddenCharge);var response=await c.GetAsync(Path(f,view:"payments"));var payments=(await response.Content.ReadFromJsonAsync<FinanceSnapshot>())!;Assert.Equal(3,payments.Payments.Length);Assert.Single(payments.Payments,x=>x.Cancelled);Assert.All(payments.Payments,x=>Assert.True(x.ChargeId==f.UnitCharge||x.ChargeId==f.OwnerCharge));var json=await response.Content.ReadAsStringAsync();foreach(var text in new[]{"private-","Private bank","HIDDEN123","5550000000","@example.test","Owner Private","Hidden Private"})Assert.DoesNotContain(text,json,StringComparison.OrdinalIgnoreCase);}
 [PostgresFact]public async Task ChargeDetailAndPaymentReferencesCannotEscapeOwnDebtScope(){var f=await Setup();using var c=TestToken.Client(factory,f.User,"RESIDENT");var detail=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f,charge:f.UnitCharge)))!;Assert.Equal(f.UnitCharge,Assert.Single(detail.Charges).Charge.Id);Assert.Equal("330.15",detail.Summary.Balance);var payments=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f,view:"payments",charge:f.UnitCharge)))!;Assert.Equal(2,payments.Total);Assert.All(payments.Payments,p=>Assert.Equal(f.UnitCharge,p.ChargeId));foreach(var id in new[]{f.TenantCharge,f.HiddenCharge,Guid.NewGuid()})Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(f,charge:id))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(f,unit:f.Other))).StatusCode);}
 [PostgresFact]public async Task ChargesAndAllocationsArePagedWithoutTruncatingTotals(){var f=await Setup();await factory.WithDb(async db=>{var unitCharge=await db.DuesCharges.FindAsync(f.UnitCharge);for(int i=0;i<51;i++){var a=new DuesAssessment(f.Property,Guid.NewGuid(),new string('c',64),new DateOnly(Today.Year,Today.Month,1).AddMonths(-4-i),1.01m,"TRY",Today,"Fixture");a.AddCharge(f.Unit);db.Add(a);var p=new Payment(f.Property,f.Unit,Guid.NewGuid(),new string('d',64),0.01m,"TRY",Today,PaymentMethod.CASH,null,"Fixture");p.Allocate(unitCharge!,0.01m);p.ValidateComplete();db.Add(p);}await db.SaveChangesAsync();});using var c=TestToken.Client(factory,f.User,"RESIDENT");var first=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f)))!;var second=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f,page:2)))!;Assert.Equal(53,first.Total);Assert.Equal(50,first.Charges.Length);Assert.Equal(3,second.Charges.Length);Assert.Empty(first.Charges.Select(x=>x.Charge.Id).Intersect(second.Charges.Select(x=>x.Charge.Id)));Assert.Equal(first.Summary,second.Summary);var p1=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f,view:"payments")))!;var p2=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f,view:"payments",page:2)))!;Assert.Equal(54,p1.Total);Assert.Equal(50,p1.Payments.Length);Assert.Equal(4,p2.Payments.Length);Assert.Empty(p1.Payments.Select(x=>x.Id).Intersect(p2.Payments.Select(x=>x.Id)));}
 [PostgresFact]public async Task ManagementAndAccountantRequireActualRolesAndMembership(){var f=await Setup();foreach(var role in new[]{"MANAGER","SITE_ADMIN","ACCOUNTANT"}){using var c=TestToken.Client(factory,f.User,role);var d=(await c.GetFromJsonAsync<FinanceSnapshot>(Path(f,role)))!;Assert.Equal(5,d.Total);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(f,"SUPER_ADMIN"))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(f,role,unit:f.Unit))).StatusCode);}using var other=TestToken.Client(factory,Guid.NewGuid().ToString(),"ACCOUNTANT");Assert.Equal(HttpStatusCode.Forbidden,(await other.GetAsync(Path(f,"ACCOUNTANT"))).StatusCode);using var admin=TestToken.Client(factory,Guid.NewGuid().ToString(),"SUPER_ADMIN");Assert.Equal(HttpStatusCode.OK,(await admin.GetAsync(Path(f,"SUPER_ADMIN"))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync(Path(f))).StatusCode);}
 [PostgresFact]public async Task RevocationExpiredRelationshipsAndAnonymousFailClosed(){var f=await Setup();using var c=TestToken.Client(factory,f.User,"RESIDENT");using var anon=TestToken.Client(factory,null,"");Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Path(f))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(f with{Property=Guid.NewGuid()}))).StatusCode);await factory.WithDb(async db=>{var o=await db.UnitOccupancies.FindAsync(f.OwnerLink);o!.End(Today.AddDays(-1));await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(f))).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.GetAsync(Path(f,"TENANT"))).StatusCode);await factory.WithDb(async db=>{var m=await db.PropertyMemberships.FindAsync(f.Membership);m!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(f,"TENANT"))).StatusCode);using var manager=TestToken.Client(factory,f.User,"MANAGER");Assert.Equal(HttpStatusCode.Forbidden,(await manager.GetAsync(Path(f,"MANAGER"))).StatusCode);}
 [PostgresFact]public async Task InvalidQueriesAndUnsupportedWritesNeverProducePaymentSuccess(){var f=await Setup();using var c=TestToken.Client(factory,f.User,"RESIDENT");foreach(var page in new[]{-1,0,10001})Assert.Equal(HttpStatusCode.BadRequest,(await c.GetAsync(Path(f,page:page))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.GetAsync(Path(f,view:"unknown"))).StatusCode);Assert.Equal(HttpStatusCode.MethodNotAllowed,(await c.PostAsJsonAsync("/api/v1/mobile/finance",new {amount="1.00"})).StatusCode);}
}
